            "method": "GRPO G=8 (best ckpt)",
            "rel_f1": 0.235,
            "evi_f1": 0.605,
            "edcr": 0.742,
            "note": "partial recovery"
          },
          {
            "method": "SFT baseline",
            "rel_f1": 0.406,
            "evi_f1": 0.798,
            "edcr": 0.712,
            "note": ""
          },
          {
            "method": "CED-as-reranker",
            "rel_f1": 0.413,
            "evi_f1": 0.802,
            "edcr": 0.668,
            "note": "inference-time only"
          },
          {
