            "rel_f1": 0.413,
            "evi_f1": 0.802,
            "edcr": 0.668,
            "extra_train": "No",
            "inference_cost": "8.5x"
          },
          {
            "method": "RSFT+CED (s44)",
            "rel_f1": 0.4655,
            "evi_f1": 0.8087,
            "edcr": 0.635,
            "extra_train": "Yes",
            "inference_cost": "1x"
